  {"skin_id":"s1_red_crimson_core","name":"Lõi Lượng Tử Đỏ (Mùa 1)","tier":"red","season_id":"season_01","sources":["season_spin"],"shop_price":null,"body":{"color":"#0A0A0C","roughness":0.25,"metalness":0.85},"layers":{"layer_1_base":{"face_colors":{"U":"#FFFFFF","D":"#FACC15","F":"#22C55E","B":"#3B82F6","L":"#F97316","R":"#EF4444"},"texture_maps":{"U":"/assets/skins/s1_red_crimson_core/albedo_u.png","D":"/assets/skins/s1_red_crimson_core/albedo_d.png","F":"/assets/skins/s1_red_crimson_core/albedo_f.png","B":"/assets/skins/s1_red_crimson_core/albedo_b.png","L":"/assets/skins/s1_red_crimson_core/albedo_l.png","R":"/assets/skins/s1_red_crimson_core/albedo_r.png"}},"layer_2_surface":{"material_type":"translucent","roughness":0.15,"metalness":0.2,"opacity":0.82,"normal_map":"/assets/skins/s1_red_crimson_core/normal.png","normal_scale":0.45},"layer_3_glow":{"enabled":true,"glow_color":"#FF2A55","emissive_map":"/assets/skins/s1_red_crimson_core/emissive_mask.png","emissive_intensity":1.6},"layer_4_animated_shader":{"enabled":true,"shader_type":"energy_pulse_sweep","speed":1.2,"primary_color":"#FF2A55","secondary_color":"#FFB703"}},"interaction_fx":{"trail_effect_id":"trail_crimson_plasma","sound_pack_id":"sound_maglev_quantum_s1"}}
  ]$catalog$;
begin
  insert into public.shop_skins(id,name,tier,season_id,appearance,shop_price,shop_currency,crates)
  select skin->>'skin_id',skin->>'name',skin->>'tier',nullif(skin->>'season_id','standard'),
    jsonb_build_object('body',skin->'body','layers',skin->'layers','interaction_fx',skin->'interaction_fx'),
    (skin->'shop_price'->>'amount')::integer,skin->'shop_price'->>'currency',
    array(select replace(source,'_crate','') from jsonb_array_elements_text(skin->'sources') source
      where source in ('core_crate','maglev_crate','quantum_crate'))
  from jsonb_array_elements(skins) skin;

  insert into public.shop_season_pool(season_id,skin_id)
  select 'season_01',skin->>'skin_id' from jsonb_array_elements(skins) skin
  where (skin->'sources') ? 'season_spin';
end;
$$;

-- Carry the palette-only inventory forward when the standalone wardrobe
-- migration was already applied. Test and fresh installs may skip that phase.
do $$
begin
  if to_regclass('public.owned_skins') is null then return; end if;
  execute 'insert into public.user_wallets(user_id)
    select distinct user_id from public.owned_skins on conflict do nothing';
  execute 'insert into public.user_inventory(user_id,kind,item_id,is_equipped)
    select owned.user_id,''skin'',owned.skin_id,coalesce(eq.skin_id=owned.skin_id,false)
    from public.owned_skins owned join public.shop_skins skin on skin.id=owned.skin_id
    left join public.equipped_skins eq on eq.user_id=owned.user_id
    on conflict do nothing';
end
$$;

commit;
